function generateFaq(){profileFromForm();var brand=state.profile.brand||'御社',service=state.profile.service||'サービス';var defaults=faqForIndustry()||[''+service+'はどのような企業・担当者に向いていますか？','導入前に必要な準備は何ですか？','他社サービスや自社運用との違いは何ですか？','成果はどの指標で計測しますか？','契約後、実装まではどのような流れですか？','セキュリティやデータの取り扱いはどうなっていますか？','対応できないケースはありますか？','料金は何によって変わりますか？','途中で施策を変更できますか？'];var existing=val('existing-faq').split(/\n+/).map(function(s){return s.trim()}).filter(Boolean);state.faqSuggestions=defaults.filter(function(d){return !existing.some(function(e){return e.slice(0,8)===d.slice(0,8)})});var out=q('faq-gap-output');out.innerHTML=state.faqSuggestions.map(function(x,i){return '<div class="ars-card ars-c6"><span class="ars-chip">FAQ '+(i+1)+'</span><p>'+esc(x)+'</p><textarea class="ars-textarea" data-faq-answer="'+i+'" placeholder="回答案を入力。未入力ならファイル生成時にテンプレート化します。"></textarea></div>'}).join('');save()}
function generateFiles(){profileFromForm();var p=state.profile,faq=state.faqSuggestions.length?state.faqSuggestions:((faqForIndustry()||['サービスの対象者は誰ですか？','導入までの流れは？','成果はどう測りますか？']).slice(0,3));var answers={};document.querySelectorAll('[data-faq-answer]').forEach(function(t){answers[t.dataset.faqAnswer]=t.value});var org={"@context":"https://schema.org","@type":"Organization","name":p.brand||'会社名',"url":p.url||'https://example.com/'};var service={"@context":"https://schema.org","@type":"Service","name":p.service||'サービス名',"provider":{"@type":"Organization","name":p.brand||'会社名',"url":p.url||'https://example.com/'},"audience":{"@type":"Audience","audienceType":p.audience||'対象顧客'},"description":p.summary||'サービス説明を入力してください。'};var faqJson={"@context":"https://schema.org","@type":"FAQPage","mainEntity":faq.map(function(question,i){return{"@type":"Question","name":question,"acceptedAnswer":{"@type":"Answer","text":answers[i]||'回答を入力してください。'}}})};var llms='# '+(p.brand||'Company')+'\n\n> '+(p.summary||'会社・サービスの公式情報です。')+'\n\n## Core pages\n- '+(p.url||'https://example.com/')+'\n\n## Service\n- '+(p.service||'Service')+' — '+(p.audience||'Target audience')+'\n\n## Important topics\n'+state.keywords.slice(0,20).map(function(k){return '- '+k.text}).join('\n');var full=llms+'\n\n## FAQ\n'+faq.map(function(x,i){return '### '+x+'\n'+(answers[i]||'回答を入力してください。')}).join('\n\n')+'\n\n## Notes\n- This file is supplemental documentation. Search and AI visibility are not guaranteed by this file alone.\n';var claude='# CLAUDE.md\n\n## Project context\n- Brand: '+(p.brand||'')+'\n- Service: '+(p.service||'')+'\n- Audience: '+(p.audience||'')+'\n\n## Content rules\n- Preserve factual claims and cite source material.\n- Do not invent metrics, customer names, prices, or AI visibility results.\n- Keep SEO and AIO changes aligned with visible page content.\n- Treat llms.txt as supplemental; do not claim it guarantees citation.\n';var kwRows=state.keywords.map(function(k){return{priority:k.priority,keyword:k.text,intent:k.intent,cluster:k.cluster,target_url:k.targetUrl||'',status:k.status||'未対策'}});var faqMd='# FAQ improvement plan\n\n'+faq.map(function(x,i){return '## '+(i+1)+'. '+x+'\n- Intent: '+(i<3?'Commercial/Decision':'Informational')+'\n- Answer: '+(answers[i]||'要作成')+'\n'}).join('\n');var impl='# Implementation plan\n\n1. JSON-LDは表示中の本文と一致する内容のみを `<script type="application/ld+json">` として主要ページへ設置。\n2. FAQPageは可視FAQと同一内容にする。\n3. llms.txt / llms-full.txtを使う場合はサイトルートで公開し、robots.txt・sitemap.xml・内部リンク・通常SEOを優先。\n4. CLAUDE.mdはWeb検索用ではなく、Claude Codeなど開発エージェントの作業指示としてリポジトリルートへ設置。\n5. Search ConsoleとGA4で施策前後を比較し、AirReach Consulting実測は別指標として保存。\n';state.generated={'web/schema/organization.jsonld':JSON.stringify(org,null,2),'web/schema/service.jsonld':JSON.stringify(service,null,2),'web/schema/faq.jsonld':JSON.stringify(faqJson,null,2),'web/llms.txt':llms,'web/llms-full.txt':full,'agents/CLAUDE.md':claude,'strategy/keyword-map.csv':toCsv(kwRows,['priority','keyword','intent','cluster','target_url','status']),'strategy/faq-plan.md':faqMd,'strategy/implementation-plan.md':impl,'data/measurement-template.csv':'date,keyword,url,impressions,clicks,position,sessions,keyEvents,aiMention,aiCitation\n'};q('implementation-guide').innerHTML='<strong>実装順：</strong> ①可視コンテンツ修正 → ②JSON-LD → ③FAQ整備 → ④robots/canonical/index確認 → ⑤llms系補助ファイル → ⑥GSC/GA4/AirReach Consultingで再計測。<br>JSON-LDやFAQは、ページ本文に存在しない事実を追加しないでください。';save()}
function seedKeywords(){profileFromForm();var s=state.profile.service||'';var brand=state.profile.brand||'';if(!s&&!brand){alert('基本情報にブランド名またはサービス名を入力してください');return}var core=s||brand;var foreign=/メディくる|CROSSONE|amasora|豊胸|レガリス|Regalis/i;var bases=[core,core+' おすすめ',core+' 比較',core+' 費用',core+' 料金',core+' 導入',core+' 事例',core+' メリット',core+' 選び方',core+' 始め方',core+' FAQ',core+' 相談',core+' 効果測定'];if(brand&&brand!==core)bases=bases.concat([brand,brand+' '+core,core+' '+brand]);var out=[],seen={};bases.forEach(function(text,idx){text=String(text||'').trim();if(!text||seen[text]||foreign.test(text))return;seen[text]=1;out.push({id:uid(),text:text,intent:/比較|料金|費用|おすすめ|選び方|相談|導入/.test(text)?'Commercial':'Informational',cluster:/料金|費用/.test(text)?'Pricing':/比較|おすすめ|選び方/.test(text)?'Comparison':'Core',priority:idx<4?'P0':idx<10?'P1':'P2',targetUrl:'',status:'未対策',why:idx<4?'購買・比較意図が強く先に対策': 'サービスに沿った候補',action:/費用|料金/.test(text)?'料金・条件を公式に明記':/比較|おすすめ|選び方/.test(text)?'比較・向いている人を整理':/事例|導入/.test(text)?'事例・導入の流れを追加':'公式ページの説明を厚くする',brandScope:brand,serviceScope:s})});state.keywords=out;save()}

function publishOfficialBaseline(){
  try{
    var byQuery={};
    // 期間は取り込んだ行の日付から数える（同期した期間を変えても 28 日扱いにしない）
    function spanDays(pick){var ds=(state.measurements||[]).filter(pick).map(function(m){return m.date}).filter(Boolean).sort();if(!ds.length)return 0;var d=Math.round((Date.parse(ds[ds.length-1])-Date.parse(ds[0]))/86400000)+1;return d>0?d:0}
    var gscTot=currentGscTotals();
    var periodDays=gscTot?gscTot.days:(spanDays(function(m){return n(m.impressions)||n(m.clicks)})||28);
    (state.measurements||[]).forEach(function(m){
      var key=(m.keyword||m.url||'').trim();
      if(!key) return;
      if(!byQuery[key]) byQuery[key]={query:key,impressions:0,clicks:0,positionSum:0,positionWeight:0,evidenceClass:'Official'};
      byQuery[key].impressions += n(m.impressions);
      byQuery[key].clicks += n(m.clicks);
      if(n(m.position)>0){byQuery[key].positionSum += n(m.position)*Math.max(n(m.impressions),1);byQuery[key].positionWeight += Math.max(n(m.impressions),1)}
    });
    var keywords=Object.keys(byQuery).map(function(k){
      var row=byQuery[k];
      row.position=row.positionWeight?row.positionSum/row.positionWeight:0;
      row.ctr=row.impressions?row.clicks/row.impressions:0;
      row.missedClicks=Math.max(0,Math.round(row.impressions*Math.max(0.06-row.ctr,0)));
      return row;
    }).sort(function(a,b){return (b.missedClicks-a.missedClicks)||(b.impressions-a.impressions)});
    // 合計はサイト全体の数字を使う。上位50語だけの合計にしない（2026-10-01: クリックが実際の約8分の1になっていた）
    // API 同期ならサイト全体（日付だけの集計＝伏せられた語句も含む）、CSV なら全行の合計
    var totalImp=gscTot?gscTot.impressions:keywords.reduce(function(s,r){return s+r.impressions},0);
    var totalClicks=gscTot?gscTot.clicks:keywords.reduce(function(s,r){return s+r.clicks},0);
    keywords=keywords.slice(0,50);
    var sessions=(state.measurements||[]).reduce(function(s,m){return s+n(m.sessions)},0);
    var keyEvents=(state.measurements||[]).reduce(function(s,m){return s+n(m.keyEvents)},0);
    var ga4Days=spanDays(function(m){return n(m.sessions)||n(m.keyEvents)})||28;
    function scaleBy(v,days){return Math.round((v/days)*30)}
    function scale(v){return scaleBy(v,periodDays)}
    var baseline={
      evidenceClass:'Official',
      source:'Studio localStorage',
      periodDays:periodDays,
      totalImpressions:totalImp,
      totalClicks:totalClicks,
      monthlyImpressions:scale(totalImp),
      monthlyClicks:scale(totalClicks),
      avgCtr:totalImp?totalClicks/totalImp:0,
      keywords:keywords,
      importedAt:new Date().toISOString()
    };
    if(sessions||keyEvents){
      baseline.ga4={evidenceClass:'Official',source:'Studio measurements',monthlySessions:scaleBy(sessions,ga4Days),monthlyKeyEvents:scaleBy(keyEvents,ga4Days)};
    }
    // サイトごとの GSC 実測（gscProperty を記録した行だけ）。以前の取り込み（別の画面で入れたサイト）は残す
    if(window.AirReachKeywordList){
      var prev=null;try{prev=JSON.parse(localStorage.getItem('airreach_official_baseline_v1')||'null')}catch(e2){}
      baseline.gscSites=window.AirReachKeywordList.mergeGscSites(prev&&prev.gscSites,window.AirReachKeywordList.gscSitesFromRows(state.measurements,periodDays));
      // サイトごとの GA4（取り込みごとに importGa4 が記録する）は、そのまま引き継ぐ
      if(prev&&prev.ga4Sites)baseline.ga4Sites=prev.ga4Sites;
    }
    localStorage.setItem('airreach_official_baseline_v1', JSON.stringify(baseline));
  }catch(e){}
}
// API 同期で受け取ったサイト全体の合計（プロパティごと）。いま選んでいる GSC サイトの分、無ければ最後に同期した分
function currentGscTotals(){var all=state.gscTotals||{};var t=all[gscPropertyInput()];if(!t){Object.keys(all).forEach(function(k){if(!t||String(all[k].updatedAt||'')>String(t.updatedAt||''))t=all[k]})}return t&&t.days>0?t:null}
// 同期の前に呼ぶ。同じサイト・同じ期間の行を消してから入れ直す（同期し直すたびに数字が積み上がらないように）
function beginGscSync(prop,start,end,totals){prop=String(prop||'').trim();state.measurements=(state.measurements||[]).filter(function(m){return !(m.gscProperty===prop&&m.date>=start&&m.date<=end)});state.gscTotals=state.gscTotals||{};if(totals&&totals.days>0)state.gscTotals[prop]=Object.assign({},totals,{updatedAt:new Date().toISOString()});else delete state.gscTotals[prop];save()}

// GSC の行を測定データに足す。property（GSC のサイト URL）が分かれば各行に記録する（診断結果の Google実測 は同じサイトの行だけを使う）
function gscPropertyInput(){return String(val('gsc-site')||(state.google&&state.google.gscSite)||'').trim()}
function mapGsc(rows,property){var prop=property!=null?String(property).trim():gscPropertyInput();if(prop&&window.AirReachKeywordList&&!window.AirReachKeywordList.gscProperty(prop))prop='';rows.forEach(function(r){var kw=r.query||r.Query||r.keyword||r.Keyword||'',url=r.page||r.Page||r.url||r.URL||'',date=r.date||r.Date||'';var m={date:date,keyword:kw,url:url,impressions:n(r.impressions||r.Impressions),clicks:n(r.clicks||r.Clicks),position:n(r.position||r.Position),sessions:0,keyEvents:0};if(prop)m.gscProperty=prop;state.measurements.push(m)});publishOfficialBaseline()}
function mapGa4(rows,site){var host=site&&site.host||'',pid=site&&site.propertyId||'';rows.forEach(function(r){var date=r.date||r.Date||'',url=r.landingPagePlusQueryString||r['Landing page + query string']||r.landingPage||r['Landing page']||r.url||'';/* サイトを指定した取り込みは、同じサイトの行とだけ合算する（別サイトの同じパスと混ぜない） */var found=state.measurements.find(function(x){return x.date===date&&(x.url===url||(!x.url&&url))&&(x.ga4Host||'')===host&&(x.ga4PropertyId||'')===pid});if(found){found.sessions+=n(r.sessions||r.Sessions);found.keyEvents+=n(r.keyEvents||r['Key events']||r.conversions||r.Conversions)}else{var m={date:date,keyword:'',url:url,impressions:0,clicks:0,position:0,sessions:n(r.sessions||r.Sessions),keyEvents:n(r.keyEvents||r['Key events']||r.conversions||r.Conversions)};if(host){m.ga4Host=host;m.ga4PropertyId=pid}state.measurements.push(m)}});publishOfficialBaseline()}
function fileHandler(id,fn){var el=q(id);if(!el)return;el.onchange=function(){var f=el.files&&el.files[0];if(!f)return;var rd=new FileReader();rd.onload=function(){try{fn(parseCsv(rd.result));save()}catch(e){alert('CSVを読み込めませんでした: '+e.message)}};rd.readAsText(f,'utf-8')}}
function demo(){state.profile={url:'https://trillion-bank.jp/',brand:'株式会社Trillion Bank',service:'AI検索対策',audience:'企業のマーケティング・経営担当者',summary:'AI検索での見え方を計測し、選ばれない理由を特定して、改善実装と再計測まで支援。'};state.competitors=[{url:'https://example-competitor-a.com/',note:'比較・料金ページが強い'},{url:'https://example-competitor-b.com/',note:'FAQと一次情報が豊富'}];seedKeywords();state.measurements=[];['2026-08-01','2026-08-15','2026-09-01','2026-09-15'].forEach(function(d,i){state.measurements.push({date:d,keyword:state.keywords[0].text,url:'https://trillion-bank.jp/airreach/',impressions:1000+i*420,clicks:26+i*15,position:18-i*2.2,sessions:21+i*12,keyEvents:1+i,aiMention:i>1?1:0,aiCitation:i>2?1:0})});fillProfile();publishOfficialBaseline();save()}
