function mergeMeasure(acc,part,err,chunk,engines){var ENGL={chatgpt:'ChatGPT',chatgpt_search:'ChatGPT（検索あり）',claude:'Claude',perplexity:'Perplexity',gemini:'Gemini',google_aio:'Google AI Overviews',google_ai_mode:'Google AI Mode',jev:'Jev'};if(err||!part){var msg=String(err&&err.message?err.message:err||'計測に失敗しました').slice(0,200);engines.forEach(function(e){if(e==='jev')return;chunk.forEach(function(p){acc.rows.push({engine:ENGL[e]||e,keyword:p.keyword,prompt:p.prompt,evidenceClass:'Observed',status:'error',error:msg,mentioned:null,cited:null,cite_source:'error',citations:[],urls_in_answer:[],competitors:[],order:[],self_rank:null,measured_at:new Date().toISOString()})});var es=acc.engineStatus[e]||(acc.engineStatus[e]={ok:false,count:0,errors:0});es.errors=(es.errors||0)+chunk.length;es.error=es.error||msg});return}(part.rows||[]).forEach(function(r){acc.rows.push(r)});Object.keys(part.engineStatus||{}).forEach(function(k){var a=acc.engineStatus[k],b=part.engineStatus[k];if(!a){acc.engineStatus[k]=Object.assign({},b);return}a.ok=!!(a.ok||b.ok);['count','answered','errors','not_shown'].forEach(function(f){a[f]=(a[f]||0)+(b[f]||0)});if(b.citeMethod==='citations')a.citeMethod='citations';else if(!a.citeMethod)a.citeMethod=b.citeMethod;a.error=a.error||b.error;a.evidenceClass=a.evidenceClass||b.evidenceClass})}
